<div class="page-head"><div><h3>Transfers</h3><p>Chronological entries for the selected month.</p></div><form class="month-form"><input type="month" name="month" value="<?= esc($month) ?>"><button class="primary">Apply</button></form></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Material</th><th>Quantity</th><th>Challan</th><th>User</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= esc($r["entry_date"]) ?></td><td><?= esc($r["code"]) ?><small><?= esc($r["description"]) ?></small></td><td><?= number_format($r["transfer_out_qty"],3) ?></td><td><?= esc($r["transfer_challan_no"]) ?></td><td><?= esc($r["user_name"]) ?></td></tr><?php endforeach; ?></tbody></table></div></section>